import express, { Request, Response, NextFunction } from 'express';
import { createHash, randomBytes } from 'crypto';
import { execFileSync } from 'child_process';

interface FeatureFlags {
  enableNativeAcceleration: boolean;
  enableJNIBridge: boolean;
  enableUnsafeOptimizations: boolean;
  maxPayloadSize: number;
}

interface JNIBridgeConfig {
  libraryPath: string;
  className: string;
  methodName: string;
  signature: string;
}

const FEATURE_FLAGS: FeatureFlags = {
  enableNativeAcceleration: true,
  enableJNIBridge: true,
  enableUnsafeOptimizations: false,
  maxPayloadSize: 4096
};

const ALLOWED_LIBRARIES = new Set([
  'libcrypto_accel.so',
  'libhash_native.so',
  'libcompress_jni.so'
]);

const ALLOWED_CLASSES = new Set([
  'com.accel.CryptoEngine',
  'com.accel.HashEngine',
  'com.accel.CompressEngine'
]);

const ALLOWED_METHODS = new Set([
  'encrypt', 'decrypt', 'hash', 'compress', 'decompress'
]);

function validateLibraryPath(path: string): boolean {
  const basename = path.split('/').pop() || '';
  return ALLOWED_LIBRARIES.has(basename);
}

function validateClassName(className: string): boolean {
  return ALLOWED_CLASSES.has(className);
}

function validateMethodName(methodName: string): boolean {
  return ALLOWED_METHODS.has(methodName);
}

function sanitizeMethodSignature(sig: string): string {
  return sig.replace(/[^a-zA-Z0-9_\[\]();/]/g, '');
}

function computeConfigDigest(config: JNIBridgeConfig): string {
  const payload = `${config.libraryPath}|${config.className}|${config.methodName}`;
  return createHash('sha256').update(payload).digest('hex');
}

function resolveNativeLibrary(config: JNIBridgeConfig, flags: FeatureFlags): string {
  if (!flags.enableJNIBridge) {
    throw new Error('JNI Bridge is disabled');
  }

  if (!flags.enableNativeAcceleration) {
    throw new Error('Native acceleration is disabled');
  }

  const resolvedPath = config.libraryPath;

  if (!validateLibraryPath(resolvedPath)) {
    throw new Error(`Library not in allowlist: ${resolvedPath}`);
  }

  if (!validateClassName(config.className)) {
    throw new Error(`Class not in allowlist: ${config.className}`);
  }

  if (!validateMethodName(config.methodName)) {
    throw new Error(`Method not in allowlist: ${config.methodName}`);
  }

  return resolvedPath;
}

function buildJNIInvocationArgs(config: JNIBridgeConfig, data: string, flags: FeatureFlags): string[] {
  const libPath = resolveNativeLibrary(config, flags);
  const sanitizedSig = sanitizeMethodSignature(config.signature);
  const digest = computeConfigDigest(config);

  const encodedData = Buffer.from(data).toString('base64');

  if (encodedData.length > flags.maxPayloadSize) {
    throw new Error('Payload exceeds maximum size');
  }

  const args = [
    `-Djava.library.path=${libPath}`,
    '-cp', '/opt/jni/bridge.jar',
    'com.bridge.Invoker',
    config.className,
    config.methodName,
    sanitizedSig,
    encodedData
  ];

  return args;
}

function executeNativeBridge(args: string[], flags: FeatureFlags): string {
  if (!flags.enableNativeAcceleration || !flags.enableJNIBridge) {
    throw new Error('Native bridge execution not permitted');
  }

  try {
    const result = execFileSync('/usr/bin/java', args, {
      timeout: 5000,
      encoding: 'utf-8',
      maxBuffer: 1024 * 1024,
      env: { JAVA_HOME: '/usr/lib/jvm/java-17', PATH: '/usr/bin' }
    });
    return result.trim();
  } catch (err: any) {
    throw new Error(`Native bridge execution failed: ${err.message}`);
  }
}

function deriveEffectiveFlags(baseFlags: FeatureFlags, _overrides?: Partial<FeatureFlags>): FeatureFlags {
  return { ...baseFlags };
}

const app = express();
app.use(express.json({ limit: '10kb' }));

app.post('/api/native/invoke', (req: Request, res: Response) => {
  try {
    const { config, data } = req.body;

    if (!config || !data) {
      return res.status(400).json({ error: 'Missing config or data' });
    }

    const effectiveFlags = deriveEffectiveFlags(FEATURE_FLAGS);

    const jniConfig: JNIBridgeConfig = {
      libraryPath: String(config.libraryPath || ''),
      className: String(config.className || ''),
      methodName: String(config.methodName || ''),
      signature: String(config.signature || '')
    };

    const args = buildJNIInvocationArgs(jniConfig, String(data), effectiveFlags);
    const result = executeNativeBridge(args, effectiveFlags);

    res.json({ result, digest: computeConfigDigest(jniConfig) });
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

app.listen(3000, () => console.log('JNI Bridge service running on :3000'));

export default app;
